-- Notifications and the Weekly Table (ARCHITECTURE v0.12 §5.5, §11.3, §11.4). `notification`: one
-- email or text to a person (a user or a contact) that something is waiting, a count and a link
-- only (plan §1.35), sent once per client, channel and dedupe key. `weekly_table`: a client's week,
-- one per client and week start: figures, the lead's note, decisions asked for and their replies,
-- next week. Tenant tables with RLS forced on app.tenant_ids, no DELETE. New tables only, so the
-- previous Worker keeps working: it never reads them. Generated by drizzle-kit; the grants,
-- row-level security and trigger at the end are hand-written, as in 0014.
CREATE TABLE "notification" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid,
	"contact_id" uuid,
	"channel" text NOT NULL,
	"kind" text NOT NULL,
	"dedupe_key" text NOT NULL,
	"link" text NOT NULL,
	"counts" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"status" text DEFAULT 'queued' NOT NULL,
	"reason" text,
	"provider_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"sent_at" timestamp with time zone,
	CONSTRAINT "notification_dedupe_key" UNIQUE("tenant_id","channel","dedupe_key"),
	CONSTRAINT "notification_channel_check" CHECK ("notification"."channel" in ('email', 'sms')),
	CONSTRAINT "notification_kind_check" CHECK ("notification"."kind" in ('items_waiting', 'weekly_table', 'reconnect', 'credits', 'lead_message', 'signoff')),
	CONSTRAINT "notification_status_check" CHECK ("notification"."status" in ('queued', 'sent', 'failed', 'skipped'))
);
