CREATE TABLE "weekly_table" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"week_start" date NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"stats" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"note" text,
	"note_by" uuid,
	"decisions" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"next_week" text,
	"setup" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"sent_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "weekly_table_week_key" UNIQUE("tenant_id","week_start"),
	CONSTRAINT "weekly_table_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "weekly_table_status_check" CHECK ("weekly_table"."status" in ('draft', 'sent')),
	CONSTRAINT "weekly_table_sent_check" CHECK (("weekly_table"."status" = 'sent') = ("weekly_table"."sent_at" is not null))
);
