-- A notification is written once and then only its delivery changes; a Weekly Table is edited in
-- place (a draft, then replies to its decisions). Neither is deleted.
GRANT SELECT, INSERT, UPDATE ON notification, weekly_table TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['notification', 'weekly_table'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
END
$$;
