-- Who was told what, and when, is a record: only the delivery's outcome changes.
CREATE TRIGGER notification_delivery_only BEFORE UPDATE OR DELETE ON notification
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('status', 'reason', 'provider_id', 'sent_at');
